fn relax_edge(dist: List[Int], e: List[Int]) -> List[Int] {
  let u = e.get_or(0, 0)
  let v = e.get_or(1, 0)
  let w = e.get_or(2, 0)
  let du = dist.get_or(u, -1)
  if du == -1 {
    return dist
  }
  let dv = dist.get_or(v, -1)
  if dv == -1 or du + w < dv {
    return dist.set(v, du + w)
  }
  return dist
}

pub fn paths(n: Int, edges: List[List[Int]], src: Int) -> List[Int] {
  var dist: List[Int] = range(0, n).map(fn(_i) => -1).set(src, 0)
  var changed = true
  while changed {
    let updated: List[Int] = edges.fold(dist, fn(d, e) => relax_edge(d, e))
    changed = updated != dist
    dist = updated
  }
  return dist
}
